fs.mkdirSync('content/git', { recursive: true });
fs.writeFileSync('content/git/modules.json', JSON.stringify(DATA.modules, null, 2) + '\n');

let nPelajaran = 0, nKuis = 0;
for (const [folder, daftar] of Object.entries(DATA.pelajaran)) {
  fs.mkdirSync(`content/git/${folder}`, { recursive: true });
  for (const p of daftar) {
    fs.writeFileSync(`content/git/${folder}/lesson-${String(p.order).padStart(2, '0')}.json`, JSON.stringify(p, null, 2) + '\n');
    nPelajaran++;
  }
}
for (const [folder, soal] of Object.entries(DATA.kuis)) {
  fs.writeFileSync(`content/git/${folder}/quiz.json`, JSON.stringify(soal, null, 2) + '\n');
  nKuis += soal.length;
}

const COURSES = 'content/courses.json';
const kursus = JSON.parse(fs.readFileSync(COURSES, 'utf8'));
const git = kursus.find((k) => k.id === 'git');
if (!git) {
  console.error('ERROR: kelas "git" tidak ditemukan di courses.json.');
  process.exit(1);
}
Object.assign(git, DATA.kursus);
fs.writeFileSync(COURSES, JSON.stringify(kursus, null, 2) + '\n');

console.log(`modules.json : content/git/modules.json (3 modul Git siap, 6 modul GitHub segera hadir)`);
console.log(`pelajaran    : ${nPelajaran} file`);
console.log(`quiz         : ${nKuis} soal di 3 modul`);
console.log(`courses.json : "Kelas Git & GitHub" -> ready`);
console.log('\nSelanjutnya: berikan GIT.md ke agent. Setelah agent selesai: node cek-modul.mjs && npm run build && npm run test:unit');
